317: // ScoreCompliance evaluates the machine-checkable applicable rules in a workspace.
318: func ScoreCompliance(record *RunRecord, task Task) {
319: 	result := Compliance{Applicable: len(task.ApplicableRules), Violated: []string{}}
320: 	machineRules := map[string]bool{"R001": true, "R002": true, "R003": true}
321: 	for _, rule := range task.ApplicableRules {
322: 		if !machineRules[rule] {
323: 			continue
324: 		}
325: 		result.Checked++
326: 		passed := false
327: 		switch rule {
328: 		case "R001":
329: 			passed = !workspaceContainsDash(record.WorkDir)
330: 		case "R002":
331: 			passed = !workspaceHasLargeFile(record.WorkDir)
332: 		case "R003":
333: 			passed = record.VerifyPassed
334: 		}
335: 		if passed {
336: 			result.Followed++
337: 		} else {
338: 			result.Violated = append(result.Violated, rule)
339: 		}
340: 	}
341: 	if result.Checked > 0 {
342: 		result.Pct = float64(result.Followed) / float64(result.Checked) * 100
343: 	}
344: 	record.Compliance = result
345: }
