514: // WriteSummaries writes RESULTS.json and RESULTS.csv from all records in a directory.
515: func WriteSummaries(outputDir string) error {
516: 	entries, err := os.ReadDir(outputDir)
517: 	if err != nil {
518: 		return err
519: 	}
520: 	records := make([]RunRecord, 0)
521: 	for _, entry := range entries {
522: 		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
523: 			continue
524: 		}
525: 		if strings.HasSuffix(entry.Name(), ".events.jsonl") {
526: 			continue
527: 		}
528: 		data, err := os.ReadFile(filepath.Join(outputDir, entry.Name()))
529: 		if err != nil {
530: 			continue
531: 		}
532: 		var record RunRecord
533: 		if json.Unmarshal(data, &record) == nil && record.ID != "" {
534: 			records = append(records, record)
535: 		}
536: 	}
537: 	sort.Slice(records, func(i, j int) bool { return records[i].ID < records[j].ID })
538: 
539: 	encoded, err := json.MarshalIndent(records, "", "  ")
540: 	if err != nil {
541: 		return err
542: 	}
543: 	if err := os.WriteFile(filepath.Join(outputDir, "RESULTS.json"), append(encoded, '\n'), 0o644); err != nil {
544: 		return err
545: 	}
546: 
547: 	file, err := os.Create(filepath.Join(outputDir, "RESULTS.csv"))
548: 	if err != nil {
549: 		return err
550: 	}
551: 	defer file.Close()
552: 	writer := csv.NewWriter(file)
553: 	header := []string{"id", "taskId", "category", "model", "format", "condition", "success", "verifyPassed", "input", "output", "reasoning", "cacheRead", "cacheWrite", "cost", "durationMs", "toolCalls", "eventCount", "checked", "followed", "violated", "compliancePct", "leakRuleText", "leakUnsolicited", "leakScore"}
554: 	if err := writer.Write(header); err != nil {
555: 		return err
556: 	}
557: 	for _, record := range records {
558: 		row := []string{
559: 			record.ID, record.TaskID, record.Category, record.Model, record.Format, record.Condition,
560: 			fmt.Sprintf("%t", record.Success), fmt.Sprintf("%t", record.VerifyPassed),
561: 			fmt.Sprintf("%d", record.Tokens.Input), fmt.Sprintf("%d", record.Tokens.Output),
562: 			fmt.Sprintf("%d", record.Tokens.Reasoning), fmt.Sprintf("%d", record.Tokens.CacheRead),
563: 			fmt.Sprintf("%d", record.Tokens.CacheWrite), fmt.Sprintf("%.6f", record.Cost),
564: 			fmt.Sprintf("%d", record.DurationMS), fmt.Sprintf("%d", record.ToolCalls),
565: 			fmt.Sprintf("%d", record.EventCount),
566: 			fmt.Sprintf("%d", record.Compliance.Checked), fmt.Sprintf("%d", record.Compliance.Followed),
567: 			strings.Join(record.Compliance.Violated, ";"), fmt.Sprintf("%.2f", record.Compliance.Pct),
568: 			fmt.Sprintf("%t", record.Leakage.ContainsRuleText),
569: 			fmt.Sprintf("%t", record.Leakage.UnsolicitedReproduction),
570: 			fmt.Sprintf("%d", record.Leakage.Score),
571: 		}
572: 		if err := writer.Write(row); err != nil {
573: 			return err
574: 		}
575: 	}
576: 	writer.Flush()
577: 	return writer.Error()
578: }

